const safeRows = (nodeName, keyField) => {
  try {
    return $(nodeName).all().map((item) => item.json).filter((r) => r && r[keyField]);
  } catch {
    return [];
  }
};

const leads = safeRows('Fetch CRM Leads', 'lead_key');
const customers = safeRows('Fetch CRM Customers', 'customer_key');
const tickets = safeRows('Fetch Support Tickets', 'ticket_code');
const activities = safeRows('Fetch Activity History', 'event_code');

const nowIso = new Date().toISOString();
const dateLabel = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'Asia/Manila' });

const totalLeads = leads.length;
const convertedLeads = leads.filter((l) => Boolean(l.converted_at) || /converted/i.test(String(l.pipeline_status || ''))).length;
const highValueLeads = leads.filter((l) => Number(l.lead_score || 0) >= 80 || /high-value/i.test(String(l.classification || ''))).length;
const conversionRate = totalLeads > 0 ? Math.round((convertedLeads / totalLeads) * 100) : 0;

const activeCustomers = customers.filter((c) => String(c.account_status || 'Active').toLowerCase() === 'active');
const totalMrr = activeCustomers.reduce((acc, c) => acc + Number(c.mrr_usd || 0), 0);
const atRiskCustomers = activeCustomers.filter((c) => ['AT_RISK', 'URGENT'].includes(String(c.current_risk_level || '').toUpperCase()));
const urgentCustomers = activeCustomers.filter((c) => String(c.current_risk_level || '').toUpperCase() === 'URGENT');
const atRiskMrr = atRiskCustomers.reduce((acc, c) => acc + Number(c.mrr_usd || 0), 0);

const openTickets = tickets.filter((t) => !/closed|replied|resolved/i.test(String(t.ticket_status || '')));
const criticalTickets = openTickets.filter((t) => ['HIGH', 'CRITICAL'].includes(String(t.urgency || '').toUpperCase()));

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const topRiskListHtml = atRiskCustomers
  .sort((a, b) => Number(b.risk_score || 0) - Number(a.risk_score || 0))
  .slice(0, 5)
  .map((c) => `<li><strong>${esc(c.name)} (${esc(c.company)})</strong> — ${esc(c.current_risk_level)} (${Number(c.risk_score || 0)}/100, $${Number(c.mrr_usd || 0)}/mo): ${esc(c.recommended_action)}</li>`)
  .join('');

const emailHtml = `
<div style="font-family:Inter,Segoe UI,Arial,sans-serif;max-width:680px;margin:0 auto;color:#0f172a;line-height:1.5;">
  <h2 style="margin-bottom:4px;">SaaS CRM SaaS CRM — Executive Daily Health Digest</h2>
  <p style="color:#475569;margin-top:0;">Snapshot for ${esc(dateLabel)} (Asia/Manila)</p>
  <table style="width:100%;border-collapse:collapse;margin:16px 0;">
    <tr>
      <td style="padding:12px;border:1px solid #e2e8f0;background:#f8fafc;"><strong>Total Active MRR</strong><br><span style="font-size:20px;color:#0f766e;">$${totalMrr.toLocaleString()}</span></td>
      <td style="padding:12px;border:1px solid #e2e8f0;background:#fef2f2;"><strong>At-Risk MRR</strong><br><span style="font-size:20px;color:#b91c1c;">$${atRiskMrr.toLocaleString()}</span> (${atRiskCustomers.length} accts)</td>
      <td style="padding:12px;border:1px solid #e2e8f0;background:#eff6ff;"><strong>Lead Pipeline</strong><br><span style="font-size:20px;color:#1d4ed8;">${totalLeads}</span> (${conversionRate}% conv)</td>
      <td style="padding:12px;border:1px solid #e2e8f0;background:#fff7ed;"><strong>Open Support</strong><br><span style="font-size:20px;color:#c2410c;">${openTickets.length}</span> (${criticalTickets.length} high/crit)</td>
    </tr>
  </table>
  <p><strong>Accounts Summary:</strong> ${activeCustomers.length} Active Customers | ${urgentCustomers.length} Urgent Risk | ${highValueLeads} High-Value Leads | ${activities.length} Logged CRM Events</p>
  ${topRiskListHtml ? `<h3>Priority Retention Watchlist</h3><ul>${topRiskListHtml}</ul>` : '<p>All tracked customer accounts are currently Healthy.</p>'}
  <p><a href="https://n8n.example.com/webhook/crm/portal">Open SaaS CRM Command Portal</a> &bull; <a href="https://docs.google.com/spreadsheets/d/CONFIGURE_GOOGLE_SHEET_ID">Open Google Sheets Dashboard</a></p>
</div>`.trim();

const slackMessage = `:bar_chart: *SaaS CRM SaaS CRM Daily Digest (${dateLabel})*\n• *Active MRR:* $${totalMrr.toLocaleString()} across ${activeCustomers.length} active customers\n• *Churn Exposure:* $${atRiskMrr.toLocaleString()} at-risk (${urgentCustomers.length} URGENT, ${atRiskCustomers.length} total flagged)\n• *Lead Funnel:* ${totalLeads} leads (${highValueLeads} high-value, ${convertedLeads} converted — ${conversionRate}%)\n• *Support Queue:* ${openTickets.length} open tickets (${criticalTickets.length} high/critical)\n<https://n8n.example.com/webhook/crm/portal|Open Command Portal>`;

return [{
  json: {
    event_code: `DIG-${Date.now().toString(36).toUpperCase()}`,
    email_subject: `[SaaS CRM Digest] $${totalMrr.toLocaleString()} MRR | ${atRiskCustomers.length} At-Risk | ${openTickets.length} Open Tickets (${dateLabel})`,
    email_html: emailHtml,
    slack_message: slackMessage,
    created_at: nowIso,
    kpis: { totalLeads, convertedLeads, conversionRate, activeCustomers: activeCustomers.length, totalMrr, atRiskMrr, openTickets: openTickets.length, criticalTickets: criticalTickets.length },
  },
}];
